create view [dbo].[tablesize] as SELECT     t.NAME AS TableName,    s.Name AS SchemaName,    p.rows AS RowCounts,    SUM(a.total_pages) * 8 AS TotalSpaceKB,    SUM(a.used_pages) * 8 AS UsedSpaceKB,    (SUM(a.total_pages) - SUM(a.used_pages)) * 8 AS UnusedSpaceKB,    CAST((SUM(a.total_pages) * 8)/1024.0/1024.0 AS DECIMAL(18,2)) AS TotalSpaceGB FROM    sys.tables t INNER Join    sys.indexes i ON t.OBJECT_ID = i.object_id INNER Join     sys.partitions p ON i.object_id = p.OBJECT_ID AND i.index_id = p.index_id INNER Join     sys.allocation_units a ON p.partition_id = a.container_id LEFT OUTER JOIN    sys.schemas s ON t.schema_id = s.schema_id WHERE    t.NAME NOT LIKE 'sys%'    AND t.is_ms_shipped = 0    AND i.OBJECT_ID > 255 GROUP BY     t.NAME , s.NAME, p.Rows 
